div.script:
                            let _leafletMap = null;
                            let _leafletMarker = null;

                            function showLiveLocationMap() {
                                const overlay = document.getElementById('location-modal-overlay');
                                overlay.classList.add('active');

                                const loadingDiv = document.getElementById('map-loading');
                                const coordsText = document.getElementById('location-coords-text');
                                loadingDiv.style.display = 'block';
                                coordsText.innerHTML = 'Waiting for GPS…';

                                // Init map once
                                if (!_leafletMap) {
                                    _leafletMap = L.map('live-map').setView([20.5937, 78.9629], 5);
                                    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                                        attribution: '© OpenStreetMap contributors',
                                        maxZoom: 19
                                    }).addTo(_leafletMap);
                                }

                                if (!navigator.geolocation) {
                                    loadingDiv.style.display = 'none';
                                    coordsText.innerHTML = '❌ Geolocation is not supported by your browser.';
                                    return;
                                }

                                navigator.geolocation.getCurrentPosition(
                                    function(pos) {
                                        const lat = pos.coords.latitude;
                                        const lng = pos.coords.longitude;
                                        const acc = pos.coords.accuracy;

                                        loadingDiv.style.display = 'none';

                                        // Move map view
                                        _leafletMap.setView([lat, lng], 16);

                                        // Remove previous marker
                                        if (_leafletMarker) {
                                            _leafletMarker.remove();
                                        }

                                        // Add marker with popup
                                        _leafletMarker = L.marker([lat, lng]).addTo(_leafletMap);
                                        var nl = '
';
                                        _leafletMarker.bindPopup(
                                            '📍 You are here' + nl +
                                            'Lat: ' + lat.toFixed(6) + nl +
                                            'Lng: ' + lng.toFixed(6) + nl +
                                            'Accuracy: ~' + Math.round(acc) + 'm'
                                        ).openPopup();

                                        // Add accuracy circle
                                        L.circle([lat, lng], {
                                            color: '#0d6efd',
                                            fillColor: '#0d6efd',
                                            fillOpacity: 0.12,
                                            radius: acc
                                        }).addTo(_leafletMap);

                                        // Force map redraw (needed when shown inside hidden element)
                                        setTimeout(function() { _leafletMap.invalidateSize(); }, 100);

                                        coordsText.innerHTML =
                                            'Lat: ' + lat.toFixed(6) + '  |  Lng: ' + lng.toFixed(6) + '' +
                                            '± ' + Math.round(acc) + 'm accuracy';
                                    },
                                    function(err) {
                                        loadingDiv.style.display = 'none';
                                        coordsText.innerHTML = '⚠️ Location error: ' + err.message;
                                    },
                                    { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
                                );

                                // Invalidate size after overlay becomes visible
                                setTimeout(function() {
                                    if (_leafletMap) _leafletMap.invalidateSize();
                                }, 200);
                            }

                            function closeLocationModal() {
                                document.getElementById('location-modal-overlay').classList.remove('active');
                            }

                            // Close on overlay click
                            document.getElementById('location-modal-overlay').addEventListener('click', function(e) {
                                if (e.target === this) closeLocationModal();
                            });
